public long countInversions(int[] arr) {
    int[] buffer = new int[arr.length];
    return mergeSort(arr, buffer, 0, arr.length - 1);
}

private long mergeSort(int[] a, int[] buf, int lo, int hi) {
    if (lo >= hi) return 0;
    int mid = lo + (hi - lo) / 2;
    long count = mergeSort(a, buf, lo, mid) + mergeSort(a, buf, mid + 1, hi);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            buf[k++] = a[i++];
        } else {
            buf[k++] = a[j++];
            count += (mid - i + 1);
        }
    }
    while (i <= mid) buf[k++] = a[i++];
    while (j <= hi) buf[k++] = a[j++];
    for (int t = lo; t <= hi; t++) a[t] = buf[t];
    return count;
}

